  function recommendOne(){const a=$('oneArea').value,arr=oneIdeas[a]||oneIdeas['마음'];const cur=$('oneSuggestion').textContent.trim();const next=arr.find(x=>x!==cur)||arr[0];$('oneSuggestion').textContent=next;oneState.area=a;oneState.text=next;oneState.date=todayKey();store.set(V15.focus,oneState)}
  function daysWithRecords(n){const c=new Date();c.setDate(c.getDate()-(n-1));const start=dateKey(c);return new Set(records.filter(r=>r.date>=start).map(r=>r.date)).size}
  function renderSchool(){[[7,5,'school7'],[30,20,'school30'],[90,60,'school90'],[365,240,'school365']].forEach(([n,target,id])=>{const d=daysWithRecords(n),p=Math.min(100,Math.round(d/target*100)),done=d>=target;if($(id+'Bar'))$(id+'Bar').style.width=p+'%';if($(id+'Text'))$(id+'Text').textContent=`${d}일 기록 · 성공 기준 ${target}일${done?' · ✓ 달성':''}`})}
  function renderPracticeIndex(){if(!$('practiceIndexTotal'))return;const d30=daysWithRecords(30);const recordRate=Math.round(d30/30*100);const actionBase=records.length||1;const actionRate=Math.round(records.filter(r=>r.action).length/actionBase*100);const actions=records.filter(r=>r.action),resultRate=actions.length?Math.round(actions.filter(r=>r.result).length/actions.length*100):0;const repeatRate=challenge&&Array.isArray(challenge.days)?Math.round(challenge.days.filter(Boolean).length/7*100):0;const restarts=restartEvents.filter(x=>{const d=new Date();d.setDate(d.getDate()-29);return x.date>=dateKey(d)}).length;const total=Math.round((recordRate+actionRate+resultRate+repeatRate)/4);$('practiceIndexTotal').textContent=total;[['piRecord',recordRate],['piAction',actionRate],['piResult',resultRate],['piRepeat',repeatRate]].forEach(([id,v])=>{$(id).textContent=v+'%';$(id+'Bar').style.width=v+'%'});$('piRestart').textContent=restarts+'회';$('piRestartBar').style.width=Math.min(100,restarts*20)+'%';$('heroScore').textContent=total;renderSchool()}
  function topHabit(rows=records){const freq={};rows.forEach(r=>{const k=(r.action||'').trim();if(k)freq[k]=(freq[k]||0)+1});const top=Object.entries(freq).sort((a,b)=>b[1]-a[1])[0];return top?top[0]:'기록이 쌓이면 표시'}
  function makeLifeBook(days=30){const rows=records.slice(0,days);if(!rows.length){toast('먼저 생활기록을 저장해 주세요.');return}const title=days===365?'나의 365일 생활연감':days===90?'나의 90일 성장책':'나의 30일 생활책';const start=new Date();start.setDate(start.getDate()-(days-1));const startKey=dateKey(start);const restarts=restartEvents.filter(x=>x.date>=startKey).length;const habit=topHabit(rows);const body=rows.map(r=>`<section><h2>${esc(r.date)} · ${esc(r.mood||'')}</h2><p><b>오늘 확인</b><br>${esc(r.done||'')}</p><p><b>하나의 실천</b><br>${esc(r.action||'')}</p><p><b>결과</b><br>${esc(r.result||'')}</p><p><b>배움</b><br>${esc(r.learn||'')}</p><p><b>다음</b><br>${esc(r.tomorrow||'')}</p></section>`).join('');const html=`<!doctype html><html lang="ko"><meta charset="utf-8"><title>${title}</title><style>body{font-family:system-ui,sans-serif;max-width:780px;margin:40px auto;padding:0 24px;line-height:1.7;color:#172036}h1{font-size:38px}.summary{padding:18px;border-radius:16px;background:#edf6f4;margin:18px 0 28px}section{padding:22px 0;border-top:1px solid #ddd}h2{font-size:20px;color:#0c8877}p{white-space:pre-wrap}</style><h1>${title}</h1><p>DAWON Life Design OS 10.0 · v16.1 · ${todayKey()}</p><div class="summary"><b>포기하지 않은 기록일</b> ${rows.length}일<br><b>다시 시작한 횟수</b> ${restarts}회<br><b>가장 자주 선택한 행동</b> ${esc(habit)}</div>${body}</html>`;download(`${title.replace(/\s+/g,'_')}_${todayKey()}.html`,html,'text/html;charset=utf-8');toast(`${title}을 만들었습니다.`)}


  function currentData(){return{date:todayKey(),done:text('done'),mood,area:$('area').value,energy:Number($('energy').value),action:text('action'),result:text('result'),learn:text('learn'),tomorrow:text('tomorrow'),selfWord:text('selfWord'),memo:text('memo')}}
  function scoreDay(d){let score=0;if(d.done)score+=20;if(d.mood)score+=20;if(d.action)score+=20;if(d.tomorrow)score+=20;if(d.selfWord)score+=20;return Math.min(100,score)}
  function summaryText(d){const parts=[];parts.push(`[${koDate(d.date)} · ${d.area}]`);parts.push(d.done?`오늘 확인: ${d.done}`:'오늘 한 일을 아직 기록하지 않았습니다.');parts.push(d.mood?`현재 감정: ${d.mood}, 에너지 ${d.energy}/10`:`현재 에너지: ${d.energy}/10`);parts.push(d.action?`하나의 실천: ${d.action}`:'오늘의 작은 실천을 정해 보세요.');if(d.result)parts.push(`실천 결과: ${d.result}`);if(d.learn)parts.push(`배운 점: ${d.learn}`);parts.push(d.tomorrow?`내일의 첫 행동: ${d.tomorrow}`:'내일 할 일을 한 가지 정해 보세요.');if(d.selfWord)parts.push(`나에게: ${d.selfWord}`);return parts.join('\n')}
  function updateDay(){const d=currentData(),s=scoreDay(d);$('dayScore').textContent=s;$('scoreRing').style.setProperty('--score',s+'%');$('cardDate').textContent=koDate(d.date);$('cardTitle').textContent=d.mood?`${d.mood}한 나를 확인합니다`:'오늘의 나를 확인합니다';$('summary').textContent=summaryText(d);$('energyValue').textContent=d.energy;const flags=[d.done||d.mood,d.action,d.result,d.learn,d.tomorrow];flags.forEach((v,i)=>$('flow'+(i+1)).classList.toggle('on',!!v));}
