  $('clearDay').addEventListener('click',()=>{clearForm();toast('입력 내용을 지웠습니다.')});
  $('saveDay').addEventListener('click',()=>{const d=currentData();if(!d.done&&!d.action&&!d.tomorrow){toast('오늘 한 일, 실천 또는 내일 할 일 중 하나를 입력하세요.');return}d.score=scoreDay(d);d.savedAt=new Date().toISOString();const idx=records.findIndex(x=>x.date===d.date);if(idx>=0)records[idx]=d;else records.unshift(d);records.sort((a,b)=>b.date.localeCompare(a.date));store.set(STORAGE.records,records);$('dayStatus').textContent=`${koDate(d.date)} 기록을 저장했습니다.`;renderReport();toast('오늘 기록을 저장했습니다.');if(window.completeFirstCoreFlow)window.completeFirstCoreFlow(d)});
  $('copySummary').addEventListener('click',()=>copy(summaryText(currentData())));$('speakSummary').addEventListener('click',()=>speak(summaryText(currentData())));

  function streak(){if(!records.length)return 0;const set=new Set(records.map(x=>x.date));let d=new Date(),n=0;for(let i=0;i<365;i++){const k=dateKey(d);if(set.has(k)){n++;d.setDate(d.getDate()-1)}else if(i===0){d.setDate(d.getDate()-1)}else break}return n}
  function renderReport(){const count=records.length,avg=count?Math.round(records.reduce((a,b)=>a+scoreDay(b),0)/count):0,acts=records.filter(x=>x.action).length,restarts=restartEvents.length,habit=topHabit(records);$('metricCount').textContent=count;$('metricAvg').textContent=avg;$('metricStreak').textContent=restarts+'회';$('metricActions').textContent=acts;if($('metricTopHabit'))$('metricTopHabit').textContent=habit.length>16?habit.slice(0,16)+'…':habit;$('heroScore').textContent=avg;$('heroRecords').textContent=count;$('heroStreak').textContent=restarts+'회';
    $('history').innerHTML=count?records.slice(0,14).map((r,i)=>`<div class="history-item" data-i="${i}"><div class="history-date">${esc(r.date.slice(5).replace('-','/'))}<br>${esc(r.mood||'감정 미선택')}</div><div><b>${esc(r.action||r.done||'기록')}</b><p>${esc(r.tomorrow||r.learn||r.result||r.memo||'')}</p></div><button class="delete-btn" data-del="${i}" aria-label="기록 삭제">×</button></div>`).join(''):'<div class="empty">저장된 기록이 없습니다.</div>';
    $$('#history .history-item').forEach(el=>el.addEventListener('click',e=>{if(e.target.dataset.del!==undefined)return;loadForm(records[Number(el.dataset.i)])}));$$('[data-del]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const i=Number(btn.dataset.del);records.splice(i,1);store.set(STORAGE.records,records);renderReport();toast('기록을 삭제했습니다.')}));
    const areas=['나','건강','관계','배움','도전','미래','돈','생활','창작','사업'];const counts=Object.fromEntries(areas.map(a=>[a,0]));records.forEach(r=>counts[r.area]=(counts[r.area]||0)+1);const max=Math.max(1,...Object.values(counts));$('areaBars').innerHTML=areas.map(a=>`<div class="bar-row"><span>${a}</span><div class="bar-track"><span style="width:${counts[a]/max*100}%"></span></div><b>${counts[a]}</b></div>`).join('');renderPracticeIndex()}
  $('exportJson').addEventListener('click',()=>download(`dawon-records-${todayKey()}.json`,JSON.stringify(records,null,2),'application/json;charset=utf-8'));
  $('exportCsv').addEventListener('click',()=>{const heads=['날짜','감정','영역','에너지','오늘한일','실천','결과','배움','내일할일','나에게','메모','점수'];const rows=records.map(r=>[r.date,r.mood,r.area,r.energy,r.done,r.action,r.result,r.learn,r.tomorrow,r.selfWord,r.memo,r.score].map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(','));download(`dawon-records-${todayKey()}.csv`,[heads.join(','),...rows].join('\n'),'text/csv;charset=utf-8')});
  $('importJson').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data))throw new Error();records=data;store.set(STORAGE.records,records);renderReport();toast('기록 백업을 불러왔습니다.')}catch(err){toast('올바른 기록 JSON 파일이 아닙니다.')}e.target.value=''});

  function speak(value){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 읽기를 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(value);u.lang='ko-KR';u.rate=.95;speechSynthesis.speak(u);toast('음성 안내를 시작합니다.')}
  $('heroGuide').addEventListener('click',()=>speak('오늘 하나만 정하세요. 3분 안에 기록하고 작은 행동을 해봅니다. 7일 뒤 달라진 것을 확인합니다. 매일 완벽할 필요는 없습니다. 쉬었다면 다시 시작하면 됩니다. 기록은 30일 생활책, 90일 성장책, 365일 생활연감으로 남길 수 있습니다.'));
  $$('.mic-btn').forEach(btn=>btn.addEventListener('click',()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Chrome 또는 Edge에서 음성 입력을 이용해 주세요.');return}const rec=new SR();rec.lang='ko-KR';rec.interimResults=false;rec.continuous=false;btn.classList.add('listening');btn.textContent='● 듣는 중';rec.onresult=e=>{const t=e.results[0][0].transcript,target=$(btn.dataset.target);target.value+=(target.value?' ':'')+t;target.dispatchEvent(new Event('input'));toast('음성을 입력했습니다.')};rec.onerror=()=>toast('음성 인식이 중단되었습니다.');rec.onend=()=>{btn.classList.remove('listening');btn.textContent=btn.dataset.target==='done'||btn.dataset.target==='action'?'🎙 음성':'🎙'};try{rec.start()}catch(e){toast('마이크 권한을 확인해 주세요.')}}));

  let challenge=store.get(STORAGE.challenge,{title:'',reason:'',reward:'',days:[false,false,false,false,false,false,false]});
  function renderChallenge(){ $('challengeTitle').value=challenge.title||'';$('challengeReason').value=challenge.reason||'';$('challengeReward').value=challenge.reward||'';$('challengeName').textContent=challenge.title||'아직 시작한 실천설계가 없습니다';const n=challenge.days.filter(Boolean).length;$('challengeCount').textContent=`${n}/7`;$('challengeBar').style.width=n/7*100+'%';$('challengeDays').innerHTML=challenge.days.map((done,i)=>`<button class="day-check ${done?'done':''}" data-day="${i}"><b>${done?'✓':i+1}</b>${i+1}일</button>`).join('');$('challengeMessage').textContent=n===7?`7일 완주! ${challenge.reward?`보상: ${challenge.reward}`:'스스로를 충분히 칭찬해 주세요.'}`:n?`${n}일의 행동이 증거로 남았습니다. 다음 하루도 작게 이어가세요.`:'실천 이름을 정하고 첫날을 체크해 보세요.';$$('[data-day]').forEach(btn=>btn.addEventListener('click',()=>{challenge.days[Number(btn.dataset.day)]=!challenge.days[Number(btn.dataset.day)];store.set(STORAGE.challenge,challenge);renderChallenge();renderPracticeIndex()}))}
  $('saveChallenge').addEventListener('click',()=>{challenge.title=text('challengeTitle');challenge.reason=text('challengeReason');challenge.reward=text('challengeReward');if(!challenge.title){toast('실천 이름을 입력하세요.');return}store.set(STORAGE.challenge,challenge);renderChallenge();renderPracticeIndex();toast('7일 실천설계를 저장했습니다.')});$('challengeSample').addEventListener('click',()=>{$('challengeTitle').value='매일 10분 걷기';$('challengeReason').value='몸과 마음의 에너지를 회복하기 위해';$('challengeReward').value='좋아하는 책 한 권';toast('예시를 입력했습니다.')});$('resetChallenge').addEventListener('click',()=>{challenge={title:'',reason:'',reward:'',days:Array(7).fill(false)};store.set(STORAGE.challenge,challenge);renderChallenge();renderPracticeIndex();toast('실천설계를 초기화했습니다.')});


