  async function checkAll(silent=false){
    if(!silent)$('worksAdminStatus').textContent='107개 PDF 실제 파일을 점검하고 있습니다…';
    $('worksCheckAll').disabled=true;$('worksCheckAll').textContent='점검 중…';
    const tasks=[];['ebook','audio','comic'].forEach(fmt=>{for(let no=0;no<FORMAT_COUNTS[fmt];no++)tasks.push([fmt,no]);});
    let done=0;const workers=Array.from({length:8},async()=>{while(tasks.length){const [fmt,no]=tasks.shift();await checkOne(fmt,no,false);done++;if(done%8===0||done===TOTAL_PDFS){updateStats();overallAudit();if(!silent)$('worksAdminStatus').textContent=`PDF 점검 ${done}/${TOTAL_PDFS} 진행 중…`;}}});
    await Promise.all(workers);render();
    const missing=[];['ebook','audio','comic'].forEach(fmt=>{for(let no=0;no<FORMAT_COUNTS[fmt];no++)if(getState(fmt,no).status==='missing')missing.push(`${formatName[fmt]} BOOK ${pad(no)}`);});
    $('worksCheckAll').disabled=false;$('worksCheckAll').textContent='107개 PDF 전체 점검';
    $('worksAdminStatus').innerHTML=missing.length?`<strong style="color:var(--danger)">PDF 파일 없음 ${missing.length}개</strong>`:`<strong>PDF 파일없음 0개</strong> · 오디오 MP3/MP4 51/51 · 만화 MP3/MP4 51/51 등록.`;
  }


  let longSpeechQueue=[],longSpeechIndex=0;
  function stopLongNarration(){longSpeechQueue=[];longSpeechIndex=0;try{speechSynthesis.cancel()}catch(e){}}
  function splitNarrationText(text){
    const raw=String(text||'').replace(/\s+/g,' ').trim(); if(!raw)return [];
    const sentences=raw.split(/(?<=[.!?。！？])\s+/); const out=[]; let cur='';
    for(const x of sentences){if((cur+' '+x).length>260&&cur){out.push(cur);cur=x}else cur+=(cur?' ':'')+x}
    if(cur)out.push(cur); return out;
  }
  function startLongNarration(text){
    if(!('speechSynthesis' in window)){motionEl('motionComicStatus').textContent='이 브라우저는 음성 낭독을 지원하지 않습니다.';return}
    stopLongNarration(); longSpeechQueue=splitNarrationText(text); longSpeechIndex=0;
    const next=()=>{if(longSpeechIndex>=longSpeechQueue.length)return;const u=new SpeechSynthesisUtterance(longSpeechQueue[longSpeechIndex++]);u.lang='ko-KR';u.rate=.95;const vs=speechSynthesis.getVoices?.()||[];const ko=vs.find(v=>/^ko/i.test(v.lang||''));if(ko)u.voice=ko;u.onend=next;u.onerror=next;speechSynthesis.speak(u);motionEl('motionComicStatus').textContent=`실시간 전체 낭독 ${longSpeechIndex}/${longSpeechQueue.length}`};next();
  }
  function openVideoPlayer(url,title,no){
    clearMotionTimer();stopSpeech();stopLongNarration();
    motionEl('motionComicModal').classList.add('show');document.body.style.overflow='hidden';
    motionEl('motionComicTitle').textContent=`BOOK ${pad(no)} · ${title||'영상'}`;
    motionEl('motionComicSub').textContent='실제 MP4 파일 재생';motionEl('motionComicBadge').textContent='REAL MP4';
    motionEl('motionComicCanvas').style.display='none';motionEl('motionComicFallback').style.display='none';
    const v=motionEl('motionComicVideo');v.style.display='block';v.src=url;v.load();v.play().catch(()=>{});
    setMotionLoading('',false);setMotionCaption('');motionEl('motionComicPage').textContent='MP4';motionEl('motionComicStatus').textContent='실제 MP4 재생 중';motionEl('motionOriginalPdf').style.display='none';
  }
  function openComicImageMovie(no){
    const item=catalog.comic[String(no)]; if(!item)return;
    clearMotionTimer();stopSpeech();stopLongNarration();motion.format='comic';motion.no=Number(no);motion.item=item;motion.page=1;motion.scene=1;motion.pages=4;motion.playing=true;motion.narration=false;motion.fallback=false;
    motionEl('motionComicModal').classList.add('show');document.body.style.overflow='hidden';motionEl('motionComicVideo').style.display='none';motionEl('motionComicFallback').style.display='none';motionEl('motionComicCanvas').style.display='block';motionEl('motionOriginalPdf').style.display='inline-flex';motionEl('motionOriginalPdf').href=hrefFor(item.url);if(location.protocol==='file:')motionEl('motionOriginalPdf').removeAttribute('target');else motionEl('motionOriginalPdf').setAttribute('target','_blank');
    motionEl('motionComicTitle').textContent=`BOOK ${pad(no)} · ${item.title}`;motionEl('motionComicSub').textContent='PDF에서 미리 렌더링한 4컷 · 로컬에서도 즉시 재생';motionEl('motionComicBadge').textContent='4-CUT LIVE';motionEl('motionPlay').textContent='❚❚ 일시정지';setMotionLoading('4컷 장면을 불러오는 중…',true);
    const img=new Image();img.onload=()=>{motion.image=img;renderComicImageScene()};img.onerror=()=>setMotionLoading('만화 이미지 파일을 찾지 못했습니다.',true);img.src=hrefFor(item.imageUrl||`works/comic-img/${pad(no)}_${safeName(item.title)}.jpg`);
  }
  function renderComicImageScene(){
    if(!motion.image)return;clearMotionTimer();const boxes=[[.04,.145,.49,.505],[.51,.145,.96,.505],[.04,.515,.49,.88],[.51,.515,.96,.88]];const b=boxes[(motion.scene-1)%4],img=motion.image,canvas=motionEl('motionComicCanvas'),ctx=canvas.getContext('2d');canvas.width=960;canvas.height=540;ctx.fillStyle='#06101f';ctx.fillRect(0,0,960,540);const sx=img.width*b[0],sy=img.height*b[1],sw=img.width*(b[2]-b[0]),sh=img.height*(b[3]-b[1]);const scale=Math.min(900/sw,500/sh),dw=sw*scale,dh=sh*scale;ctx.drawImage(img,sx,sy,sw,sh,(960-dw)/2,(540-dh)/2,dw,dh);motionEl('motionComicPage').textContent=`${motion.scene}컷 / 4`;motionEl('motionComicStatus').textContent='PDF 4컷 라이브 재생';setMotionLoading('',false);animateMotionCanvas();clearMotionTimer();if(motion.playing)motion.timer=setTimeout(()=>{if(motion.scene<4){motion.scene++;renderComicImageScene()}else{motion.playing=false;motionEl('motionPlay').textContent='▶ 처음부터'}},motionDelay());
  }

  $('worksGrid')&&$('worksGrid').addEventListener('click',e=>{
    const v=e.target.closest('.media-video-btn');if(v){e.preventDefault();openVideoPlayer(v.dataset.videoUrl,v.dataset.videoTitle,Number(v.dataset.no));return}
    const m=e.target.closest('[data-motion-format]');
    if(m){e.preventDefault();if(m.dataset.motionFormat==='comic')openComicImageMovie(Number(m.dataset.no));else openMotionComic('audio',Number(m.dataset.no));return}
    const n=e.target.closest('.live-narration-btn');if(n){e.preventDefault();openLiveNarration(Number(n.dataset.no))}
  });
  function fillAdminNos(){
    const sel=$('workAdminNo'),fmt=$('workAdminFormat').value,cur=Number(sel.value||0);
    sel.innerHTML='';
    for(let no=0;no<FORMAT_COUNTS[fmt];no++)sel.insertAdjacentHTML('beforeend',`<option value="${no}">${pad(no)}</option>`);
    sel.value=String(Math.min(cur,FORMAT_COUNTS[fmt]-1));
  }
  function loadAdmin(){
    const fmt=$('workAdminFormat').value,no=$('workAdminNo').value||'0',item=catalog[fmt]?.[String(no)]||defaults[fmt]?.[String(no)]||{};
    $('workAdminTitle').value=item.title||'';
    $('workAdminUrl').value=item.url||'';
    $('workAdminAudioUrl').value=item.audioUrl||'';
    $('workAdminVideoUrl').value=item.videoUrl||'';
    $('workAdminAudioWrap').classList.toggle('disabled',fmt==='ebook');
    $('workAdminAudioUrl').disabled=fmt==='ebook';
    $('workAdminVideoWrap').classList.toggle('disabled',fmt==='ebook');
    $('workAdminVideoUrl').disabled=fmt==='ebook';
    const st=getState(fmt,no).status;
    $('worksAdminStatus').textContent=`${formatName[fmt]} BOOK ${pad(no)} · ${stateLabel(st)} · PDF/MP3/MP4 편집`;
  }
  fillAdminNos();
  $('workAdminFormat').addEventListener('change',()=>{
    fillAdminNos();active=$('workAdminFormat').value;page=1;
    document.querySelectorAll('.works-tab').forEach(b=>b.classList.toggle('active',b.dataset.workFormat===active));
    loadAdmin();render();
  });
  $('workAdminNo').addEventListener('change',loadAdmin);
  $('worksLoadCurrent').addEventListener('click',loadAdmin);
  $('workAdminSave').addEventListener('click',()=>{
    const fmt=$('workAdminFormat').value,no=String($('workAdminNo').value),title=$('workAdminTitle').value.trim(),url=$('workAdminUrl').value.trim(),audioUrl=$('workAdminAudioUrl').value.trim(),videoUrl=$('workAdminVideoUrl').value.trim();
    if(!title){$('worksAdminStatus').textContent='작품명을 입력해 주세요.';return}
    const desc=fmt==='audio'?`오디오북 BOOK ${pad(no)} · PDF · MP3/MP4 · 전체 실시간 낭독`:fmt==='comic'?`만화책 BOOK ${pad(no)} · PDF · MP3 · MP4 · 원스톱 재제작`:`전자책 BOOK ${pad(no)} · 개별 PDF`;
    catalog[fmt][no]={...(catalog[fmt][no]||{}),title,url,audioUrl:fmt==='ebook'?'':audioUrl,videoUrl:fmt==='ebook'?'':videoUrl,desc,seeded:false};
    save();setState(fmt,no,'unchecked');active=fmt;page=Math.ceil((Number(no)+1)/perPage);$('worksSearch').value='';
    document.querySelectorAll('.works-tab').forEach(b=>b.classList.toggle('active',b.dataset.workFormat===active));
    $('worksAdminStatus').textContent=`${formatName[fmt]} BOOK ${pad(no)} 등록 저장 완료.`;render();checkOne(fmt,Number(no));
  });
  $('workAdminCheckOne').addEventListener('click',async()=>{const fmt=$('workAdminFormat').value,no=Number($('workAdminNo').value||0);$('worksAdminStatus').textContent=`${formatName[fmt]} BOOK ${pad(no)} 실제 파일 점검 중…`;const r=await checkOne(fmt,no);$('worksAdminStatus').textContent=`${formatName[fmt]} BOOK ${pad(no)} · ${stateLabel(r.status)}${r.httpStatus?` · HTTP ${r.httpStatus}`:''}`;});
  $('workAdminClear').addEventListener('click',()=>{const fmt=$('workAdminFormat').value,no=String($('workAdminNo').value);catalog[fmt][no]=clone(defaults[fmt][no]);save();setState(fmt,no,'unchecked');loadAdmin();render();$('worksAdminStatus').textContent=`${formatName[fmt]} BOOK ${pad(no)}을 기본 개별 PDF 경로로 복원했습니다.`;});
  $('workCatalogExport').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:'12.0-live-motion-media',numbering:'ebook 00-04 / audio comic 00-50',exportedAt:new Date().toISOString(),catalog},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='dawon-works-v14-catalog.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);$('worksAdminStatus').textContent='107개 PDF와 MP3·MP4·원스톱 만화영화 연결정보를 JSON으로 백업했습니다.';});
  $('worksCheckAll').addEventListener('click',()=>checkAll(false));
  $('worksMissingExport').addEventListener('click',()=>{
    const missing=[];['ebook','audio','comic'].forEach(fmt=>{for(let no=0;no<FORMAT_COUNTS[fmt];no++){const item=catalog[fmt][String(no)]||{},st=getState(fmt,no);if(st.status==='missing'||!item.url)missing.push({format:formatName[fmt],book:pad(no),title:item.title||'',url:item.url||'',status:stateLabel(st.status)});}});
    const audioPending=Array.from({length:51},(_,no)=>{const item=catalog.audio[String(no)]||{};return !item.audioUrl?{format:'오디오북 음원',book:pad(no),title:item.title||'',status:'음원 준비 중'}:null;}).filter(Boolean);
    const report={checkedAt:new Date().toISOString(),pdfMissing:missing,audioPending,audioLinked:audioLinked()};
    const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='dawon-file-missing-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);
    $('worksAdminStatus').textContent=`PDF 파일없음 ${missing.length}개 · 오디오 MP3 미등록 ${audioPending.length}개 목록을 저장했습니다.`;
  });


